export function Gate({
  gateTitle = "{{gateTitle}}",
  condition1 = "{{condition1}}",
  condition1Met = {{condition1Met}},
  condition2 = "{{condition2}}",
  condition2Met = {{condition2Met}},
  open = {{open}},
}) {
  const rows = [
    { label: condition1, met: condition1Met },
    { label: condition2, met: condition2Met },
    { label: "No open P1 incidents", met: true },
  ];
  return (
    <div style={{ fontFamily: "system-ui, sans-serif", maxWidth: 380, padding: 20, background: "#FAF7F2",
      color: "#241430", borderRadius: 14, border: "1.5px solid #24143020" }}>
      <h3 style={{ margin: "0 0 12px", fontSize: 16, fontWeight: 700 }}>{gateTitle}</h3>
      <ul style={{ listStyle: "none", margin: "0 0 14px", padding: 0, display: "flex", flexDirection: "column", gap: 6 }}>
        {rows.map((r, i) => (
          <li key={i} style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 14, color: r.met ? "#2f8a52" : "#b23b3b" }}>
            <span style={{ display: "inline-flex" }} dangerouslySetInnerHTML={{ __html: r.met ? "<svg viewBox=\"0 0 16 16\" width=\"16\" height=\"16\" fill=\"none\" aria-hidden=\"true\"><path d=\"M3 8.5l3 3 7-7\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>" : "<svg viewBox=\"0 0 16 16\" width=\"16\" height=\"16\" fill=\"none\" aria-hidden=\"true\"><path d=\"M4 4l8 8M12 4l-8 8\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg>" }} />
            <span>{r.label} — {r.met ? "Met" : "Not met"}</span>
          </li>
        ))}
      </ul>
      <p style={{ margin: 0, padding: "10px 12px", borderRadius: 8, fontWeight: 600, fontSize: 14,
        background: open ? "#2f8a521a" : "#b23b3b1a", color: open ? "#2f8a52" : "#b23b3b" }}>
        {open ? "Gate open — ready to proceed" : "Gate closed — resolve blocking conditions"}
      </p>
    </div>
  );
}
